package com.govweb.service;
import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize;
@RestController @RequestMapping("/api/services") @CrossOrigin(origins="http://localhost:5173") public class ServiceController { private final ServiceRepository repo; public ServiceController(ServiceRepository repo){this.repo=repo;} @GetMapping public java.util.List<Service> all(){return repo.findByActiveTrue();} @PostMapping @PreAuthorize("hasAnyRole('OFFICER','SUPER_ADMIN')") @ResponseStatus(HttpStatus.CREATED) public Service create(@Valid @RequestBody Service service){service.setFee(1500);return repo.save(service);} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('OFFICER','SUPER_ADMIN')") public Service update(@PathVariable Long id,@Valid @RequestBody Service s){s.setId(id);s.setFee(1500);return repo.save(s);} }
